def create_module_permission_rows(apps, schema_editor):
    Permission = apps.get_model("auth", "Permission")
    ContentType = apps.get_model("contenttypes", "ContentType")
    content_type, _ = ContentType.objects.get_or_create(app_label="progeo", model="usermodulepermissions")
    existing = set(Permission.objects.filter(content_type=content_type).values_list("codename", flat=True))
    Permission.objects.bulk_create([
        Permission(content_type=content_type, codename=code, name=label)
        for code, label in MODULE_PERMISSION_ROWS
        if code not in existing
    ])


